const STOP = new Set('a an the of to in on for and or is are be do does can i you we it its my your with at by from as that this what how when which who about if not no any'.split(' '));
const toks = s => s.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(w => w && !STOP.has(w)).map(w => w.length > 3 ? w.replace(/(ies|es|s)$/, '') : w);

const docs = $input.all().map(i => ({file: (i.binary && i.binary.data && i.binary.data.fileName) || 'unknown.md', text: String(i.json.data || i.json.text || '')}));
const chunks = [];
for (const d of docs) {
  const lines = d.text.split(/\r?\n/).filter(l => l.trim());
  const title = (lines[0] || '').replace(/^#+\s*/, '');
  const sents = lines.slice(1).join(' ').split(/(?<=[.!?])\s+/).filter(Boolean);
  for (let i = 0; i < sents.length; i++) chunks.push({file: d.file, section: title, para: i + 1, text: sents.slice(i, i + 2).join(' ')});
}
const df = {};
chunks.forEach(c => { c.tf = {}; toks(c.text + ' ' + c.section).forEach(w => c.tf[w] = (c.tf[w] || 0) + 1); Object.keys(c.tf).forEach(w => df[w] = (df[w] || 0) + 1); });
const N = chunks.length, idf = {};
Object.keys(df).forEach(w => idf[w] = Math.log(1 + N / df[w]));
chunks.forEach(c => { let n = 0; const v = {}; Object.keys(c.tf).forEach(w => { v[w] = (1 + Math.log(c.tf[w])) * idf[w]; n += v[w] * v[w]; }); n = Math.sqrt(n); Object.keys(v).forEach(w => v[w] = +(v[w] / n).toFixed(5)); c.vec = v; delete c.tf; });
const index = {built_at: new Date().toISOString(), docs: docs.length, chunks: N, idf, items: chunks};
const bin = await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(index), 'utf8'), 'rag_index.json', 'application/json');
return [{json: {docs: docs.length, chunks: N}, binary: {data: bin}}];

const STOP = new Set('a an the of to in on for and or is are be do does can i you we it its my your with at by from as that this what how when which who about if not no any'.split(' '));
const toks = s => s.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(w => w && !STOP.has(w)).map(w => w.length > 3 ? w.replace(/(ies|es|s)$/, '') : w);

const cfg = $('Config').first().json;
const index = JSON.parse((await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8'));
const question = String(($('Question webhook').first().json.body || {}).question || '').trim();
if (!question) throw new Error('Missing question');
const tf = {}; toks(question).forEach(w => tf[w] = (tf[w] || 0) + 1);
const q = {}; let n = 0;
Object.keys(tf).forEach(w => { if (index.idf[w]) { q[w] = (1 + Math.log(tf[w])) * index.idf[w]; n += q[w] * q[w]; } });
n = Math.sqrt(n) || 1;
const scored = index.items.map(c => { let s = 0; Object.keys(q).forEach(w => { if (c.vec[w]) s += (q[w] / n) * c.vec[w]; }); return {file: c.file, section: c.section, para: c.para, text: c.text, score: +s.toFixed(3)}; })
  .sort((a, b) => b.score - a.score);
const top = []; const seen = new Set();
for (const c of scored) { const k = c.file + c.para; if (c.score > 0 && !seen.has(k) && top.length < Number(cfg.top_k)) { seen.add(k); top.push(c); } }
return [{json: {question, top, best: top.length ? top[0].score : 0, enough: top.length > 0 && top[0].score >= Number(cfg.min_score)}}];

